using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;
public static class RecoveredConnectorImporter {
 const string Src="Assets/Recovery/ExtraScene/ChargerLine/",Dst="Assets/RecoveredS07/Environment/";
 public static RecoveredConnectorControls Import(){
  var b=JsonUtility.FromJson<S07RecoveryImporter.Blueprint>(File.ReadAllText(Src+"blueprint.json"));var d=JsonUtility.FromJson<S07RecoveryImporter.MeshData>(File.ReadAllText(b.meshes[0].file));var mesh=new Mesh{name=d.name};mesh.vertices=d.vertices;mesh.normals=d.normals;if(d.tangents.Length==d.vertices.Length)mesh.tangents=d.tangents;mesh.uv=d.uv;if(d.colors.Length==d.vertices.Length){if(d.colorUNorm8){var c=Array.ConvertAll(d.colors,x=>new Color32((byte)x.r,(byte)x.g,(byte)x.b,(byte)x.a));mesh.colors32=c;}else mesh.colors=d.colors;}mesh.subMeshCount=d.submeshes.Length;for(int i=0;i<d.submeshes.Length;i++)mesh.SetTriangles(d.submeshes[i].indices,i);mesh.RecalculateBounds();Save(mesh,Dst+"NativeConnectorMesh.asset");
  var mats=new Dictionary<string,Material>();foreach(var e in b.materials){var shader=Shader.Find(e.id=="8"?"Recovered/CarRP/Lit/TransparentChargerLine/Variant3":"Recovered/CarRP/Lit/Opaque/Variant9");if(shader==null||ShaderUtil.ShaderHasError(shader))throw new InvalidOperationException("Connector shader failed: "+e.name);var m=new Material(shader){name=e.name,renderQueue=e.renderQueue};foreach(var c in e.colors)if(m.HasProperty(c.name))m.SetColor(c.name,c.value);foreach(var f in e.floats){int p=shader.FindPropertyIndex(f.name);if(p<0)continue;var t=shader.GetPropertyType(p);if(t==ShaderPropertyType.Float||t==ShaderPropertyType.Range||t==ShaderPropertyType.Int)m.SetFloat(f.name,f.value);}Save(m,Dst+"ConnectorMaterial_"+e.id+".mat");mats[e.id]=m;}
  var ctrl=new GameObject("NativeConnectors").AddComponent<RecoveredConnectorControls>();ctrl.covers=new[]{GameObject.Find("ChargerL").transform,GameObject.Find("ChargerR").transform};ctrl.parts=new Transform[2];ctrl.lineMaterials=new Material[2];ctrl.positions=new[]{new Vector3(1.822000027f,1.037999988f,-.947000027f),new Vector3(1.822000027f,1.037999988f,.947000027f)};ctrl.rotations=new[]{new Quaternion(0,-1,0,0),Quaternion.identity};for(int i=0;i<2;i++){var go=new GameObject(i==0?"ChargerLineL":"ChargerLineR");go.transform.SetParent(ctrl.transform,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;var line=new Material(mats["8"]){name="NativeLine_"+i};Save(line,Dst+"NativeLine_"+i+".mat");go.AddComponent<MeshRenderer>().sharedMaterials=new[]{line,mats["9"]};ctrl.parts[i]=go.transform;ctrl.lineMaterials[i]=line;}ctrl.SetVisible(false);return ctrl;
 }
 static void Save(UnityEngine.Object o,string path){AssetDatabase.DeleteAsset(path);AssetDatabase.CreateAsset(o,path);}
}
